import{_ as a,o as r,c as i,al as t}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/peripherals/mavlink_peripherals.md","filePath":"ko/peripherals/mavlink_peripherals.md"}'),o={name:"ko/peripherals/mavlink_peripherals.md"};function n(l,e,c,s,p,_){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="mavlink-peripherals-gcs-osd-gimbal-camera-companion" tabindex="-1">MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion) <a class="header-anchor" href="#mavlink-peripherals-gcs-osd-gimbal-camera-companion" aria-label="Permalink to &quot;MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)&quot;">​</a></h1><p>Ground Control Stations (GCS), <a href="./../peripherals/osd#mavlink-osd">MAVLink On-Screen Displays (OSD)</a>, MAVLink <a href="./../camera/mavlink_v2_camera">Cameras</a> and <a href="./../advanced/gimbal_control">Gimbals</a>, <a href="./../peripherals/remote_id">Remote IDs</a>, Companion Computers, <a href="./../peripherals/adsb_flarm">ADS-B receivers</a>, and other MAVLink peripherals interact with PX4 using separate MAVLink streams, sent via different serial ports.</p><p>In order to configure that a particular serial port is used for MAVLink traffic with a particular peripheral, we use <a href="./../peripherals/serial_configuration">Serial Port Configuration</a>, assigning one of the abstract &quot;MAVLink instance&quot; configuration parameters to the desired port. We then set other properties of the MAVLink channel using the parameters associated with our selected MAVLink instance, so that they match the requirements of our particular peripheral.</p><p>The most relevant parameters are described below (the full set are listed in the <a href="./../advanced_config/parameter_reference#mavlink">Parameter Reference &gt; MAVLink</a>).</p><h2 id="mavlink-인스턴스" tabindex="-1">MAVLink 인스턴스 <a class="header-anchor" href="#mavlink-인스턴스" aria-label="Permalink to &quot;MAVLink 인스턴스&quot;">​</a></h2><p>In order to assign a particular peripheral to a serial port we use the concept of a <em>MAVLink instance</em>.</p><p>Each MAVLink instance represents a particular MAVLink configuration that you can apply to a particular port. At time of writing three MAVLink <em>instances</em> are defined, each represented by a parameter <a href="#MAV_X_CONFIG">MAV_X_CONFIG</a>, where X is 0, 1, 2.</p><p>Each instance has associated parameters that you can use to define the properties of the instance on that port, such as the set of streamed messages (see <a href="#MAV_X_MODE">MAV_X_MODE</a> below), data rate (<a href="#MAV_X_RATE">MAV_X_RATE</a>), whether incoming traffic is forwarded to other MAVLink instances (<a href="#MAV_X_FORWARD">MAV_X_FORWARD</a>), and so on.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>MAVLink instances are an abstract concept for a particular MAVLink configuration. The number in the name means nothing; you can assign any instance to any port.</p></div><p>각 인스턴스의 매개변수는 아래와 같습니다.</p><ul><li><a id="MAV_X_CONFIG"></a><a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_X_CONFIG</a> - Set the serial port (UART) for this instance &quot;X&quot;, where X is 0, 1, 2. It can be any unused port, e.g.: <code>TELEM2</code>, <code>TELEM3</code>, <code>GPS2</code> etc. For more information see <a href="./../peripherals/serial_configuration">Serial Port Configuration</a>.</li><li><a id="MAV_X_MODE"></a><a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_X_MODE</a> - Specify the <a href="./../mavlink/mavlink_profiles">MAVLink profile</a> for the instance, such as <em>Normal</em> or <em>OSD</em>. Profiles define a particular set of streamed messages and their rates — you should choose a profile that is appropriate for your channel and the peripheral.</li><li><a id="MAV_X_RATE"></a><a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_X_RATE</a> - Set the maximum <em>data rate</em> for this instance (bytes/second). <ul><li>이는 개별 메시지의 모든 스트림에 대한 결합 비율입니다 (총 비율이이 값을 초과하면 개별 메시지에 대한 비율이 감소됨).</li><li>기본 설정은 일반적으로 허용되지만 원격 분석 링크가 포화 상태가 되고, 너무 많은 메시지가 삭제되는 경우에는 감소할 수 있습니다.</li><li>값이 0이면 데이터 속도가 이론적인 값의 절반으로 설정됩니다.</li></ul></li><li><a id="MAV_X_FORWARD"></a><a href="./../advanced_config/parameter_reference#MAV_0_FORWARD">MAV_X_FORWARD</a> - Enable forwarding of MAVLink packets received by the current instance onto other interfaces. 예를 들어 GCS가 보조 컴퓨터에 연결된 MAVLink 지원 카메라와 통신할 수 있도록 GCS와 보조 컴퓨터간에 메시지를 전송에 사용할 수 있습니다.</li></ul><p>Next you need to set the baud rate for the serial port you assigned above (in <code>MAV_X_CONFIG</code>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You will need to reboot PX4 to make the parameter available (i.e. in QGroundControl).</p></div><p>The parameter used will depend on the <a href="./../advanced_config/parameter_reference#serial">assigned serial port</a> - for example: <code>SER_GPS1_BAUD</code>, <code>SER_TEL2_BAUD</code>, etc. 사용하는 값은 연결 유형과 연결된 MAVLink 주변 장치에 따라 달라집니다.</p><h2 id="default_ports" tabindex="-1">Default MAVLink Ports <a class="header-anchor" href="#default_ports" aria-label="Permalink to &quot;Default MAVLink Ports {#default_ports}&quot;">​</a></h2><h3 id="telem1" tabindex="-1">TELEM1 <a class="header-anchor" href="#telem1" aria-label="Permalink to &quot;TELEM1&quot;">​</a></h3><p>The <code>TELEM 1</code> port is almost always configured by default for the GCS telemetry stream (&quot;Normal&quot;).</p><p>To support this there is a <a href="./../peripherals/serial_configuration#default_port_mapping">default serial port mapping</a> of MAVLink instance 0 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_0_CONFIG</a> = <code>TELEM 1</code></li><li><a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_0_MODE</a> = <code>Normal</code></li><li><a href="./../advanced_config/parameter_reference#MAV_0_RATE">MAV_0_RATE</a>= <code>1200</code> Bytes/s</li><li><a href="./../advanced_config/parameter_reference#MAV_0_FORWARD">MAV_0_FORWARD</a> = <code>True</code></li><li><a href="./../advanced_config/parameter_reference#SER_TEL1_BAUD">SER_TEL1_BAUD</a> = <code>57600</code></li></ul><h3 id="telem2" tabindex="-1">TELEM2 <a class="header-anchor" href="#telem2" aria-label="Permalink to &quot;TELEM2&quot;">​</a></h3><p>The <code>TELEM 2</code> port usually configured by default for a companion computer telemetry stream (&quot;Onboard&quot;).</p><p>To support this there is a <a href="./../peripherals/serial_configuration#default_port_mapping">default serial port mapping</a> of MAVLink instance 0 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference#MAV_0_CONFIG">MAV_1_CONFIG</a> = <code>TELEM 2</code></li><li><a href="./../advanced_config/parameter_reference#MAV_0_MODE">MAV_1_MODE</a> = <code>Onboard</code></li><li><a href="./../advanced_config/parameter_reference#MAV_0_RATE">MAV_1_RATE</a>= <code>0</code> (Half maximum)</li><li><a href="./../advanced_config/parameter_reference#MAV_0_FORWARD">MAV_1_FORWARD</a> = <code>Disabled</code></li><li><a href="./../advanced_config/parameter_reference#SER_TEL2_BAUD">SER_TEL2_BAUD</a> = <code>921600</code></li></ul><h3 id="ethernet" tabindex="-1">ETHERNET <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;ETHERNET&quot;">​</a></h3><p>Pixhawk 5x devices (and later) that have an Ethernet port, configure it by default to connect to a GCS:</p><p>On this hardware, there is a <a href="./../peripherals/serial_configuration#default_port_mapping">default serial port mapping</a> of MAVLink instance 2 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference#MAV_2_CONFIG">MAV_2_CONFIG</a> = <code>Ethernet</code> (1000)</li><li><a href="./../advanced_config/parameter_reference#MAV_2_BROADCAST">MAV_2_BROADCAST</a> = <code>1</code></li><li><a href="./../advanced_config/parameter_reference#MAV_2_MODE">MAV_2_MODE</a> = <code>0</code> (normal/GCS)</li><li><a href="./../advanced_config/parameter_reference#MAV_2_RADIO_CTL">MAV_2_RADIO_CTL</a> = <code>0</code></li><li><a href="./../advanced_config/parameter_reference#MAV_2_RATE">MAV_2_RATE</a> = <code>100000</code></li><li><a href="./../advanced_config/parameter_reference#MAV_2_REMOTE_PRT">MAV_2_REMOTE_PRT</a>= <code>14550</code> (GCS)</li><li><a href="./../advanced_config/parameter_reference#MAV_2_UDP_PRT">MAV_2_UDP_PRT</a> = <code>14550</code> (GCS)</li></ul><p>For more information see: <a href="./../advanced_config/ethernet_setup">PX4 Ethernet Setup</a></p><h2 id="device-specific-setup" tabindex="-1">Device Specific Setup <a class="header-anchor" href="#device-specific-setup" aria-label="Permalink to &quot;Device Specific Setup&quot;">​</a></h2><p>Links to setup instructions for specific MAVLink components:</p><ul><li><a href="./../camera/mavlink_v2_camera#px4-configuration">MAVLink Cameras (Camera Protocol v2) &gt; PX4 Configuration</a></li><li><a href="./../advanced/gimbal_control#mavlink-gimbal-mnt-mode-out-mavlink">Gimbal Configuration &gt; MAVLink Gimbal (MNT_MODE_OUT=MAVLINK)</a></li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../mavlink/mavlink_profiles">MAVLink Profiles</a></li><li><a href="./../peripherals/serial_configuration">Serial Port Configuration</a></li><li><a href="./../advanced_config/ethernet_setup#px4-mavlink-serial-port-configuration">PX4 Ethernet Setup &gt; PX4 MAVLink Serial Port Configuration</a></li><li><a href="./../hardware/serial_port_mapping">Serial Port Mapping</a></li></ul>',33)])])}const h=a(o,[["render",n]]);export{f as __pageData,h as default};
